  internal static class CadPreviewStyle {
    public static readonly Color Background=Color.FromArgb(230,233,237);
    static int Rgb(byte[] bytes,int pixel){int i=pixel*4;return bytes[i+2]<<16|bytes[i+1]<<8|bytes[i];}
    static bool Match(int color,int background){return Math.Abs((color>>16&255)-(background>>16&255))+Math.Abs((color>>8&255)-(background>>8&255))+Math.Abs((color&255)-(background&255))<=30;}
    static bool BlackRow(byte[] bytes,int width,int row){for(int x=0;x<width;x++){int color=Rgb(bytes,row*width+x);if((color>>16&255)>5||(color>>8&255)>5||(color&255)>5)return false;}return true;}
    public static Bitmap Frame(Image source){
      using(var normalized=Prepare(source))using(var original=new Bitmap(normalized.Width,normalized.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb)){
        using(var graphics=Graphics.FromImage(original))graphics.DrawImageUnscaled(normalized,0,0);int width=original.Width,height=original.Height,left=width,right=-1,top=height,bottom=-1;
        var data=original.LockBits(new Rectangle(0,0,width,height),System.Drawing.Imaging.ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);var pixels=new byte[width*height*4];try{Marshal.Copy(data.Scan0,pixels,0,pixels.Length);}finally{original.UnlockBits(data);}
        int background=Background.R<<16|Background.G<<8|Background.B;
        for(int y=0;y<height;y++)for(int x=0;x<width;x++){if(Match(Rgb(pixels,y*width+x),background))continue;left=Math.Min(left,x);right=Math.Max(right,x);top=Math.Min(top,y);bottom=Math.Max(bottom,y);}
        if(right<left)return new Bitmap(original);int padding=Math.Max(24,(int)(Math.Max(right-left,bottom-top)*.08));left=Math.Max(0,left-padding);right=Math.Min(width-1,right+padding);top=Math.Max(0,top-padding);bottom=Math.Min(height-1,bottom+padding);return original.Clone(new Rectangle(left,top,right-left+1,bottom-top+1),System.Drawing.Imaging.PixelFormat.Format32bppArgb);
      }
    }
    public static Bitmap Prepare(Image source){
      using(var original=new Bitmap(source.Width,source.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb)){
        using(var graphics=Graphics.FromImage(original))graphics.DrawImageUnscaled(source,0,0);
        int width=original.Width,height=original.Height;var bounds=new Rectangle(0,0,width,height);
        var data=original.LockBits(bounds,System.Drawing.Imaging.ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);
        var pixels=new byte[width*height*4];try{Marshal.Copy(data.Scan0,pixels,0,pixels.Length);}finally{original.UnlockBits(data);}
        int top=0,bottom=height-1;while(top<bottom&&BlackRow(pixels,width,top))top++;while(bottom>top&&BlackRow(pixels,width,bottom))bottom--;
        var frame=new Dictionary<int,int>();Action<int> sample=pixel=>{int color=Rgb(pixels,pixel),count;frame.TryGetValue(color,out count);frame[color]=count+1;};
        for(int x=0;x<width;x++){sample(top*width+x);sample(bottom*width+x);}for(int y=top+1;y<bottom;y++){sample(y*width);sample(y*width+width-1);}
        int background=frame.OrderByDescending(pair=>pair.Value).First().Key,r=background>>16&255,g=background>>8&255,b=background&255;
        // Ordinary shaded thumbnails retain their materials. Normalize the old flat, saturated-background thumbnails only.
        if(Math.Max(r,Math.Max(g,b))-Math.Min(r,Math.Min(g,b))<60)return new Bitmap(source);
        var model=new bool[width*height];int left=width,right=-1,first=height,last=-1,countModel=0,white=0;
        for(int y=top;y<=bottom;y++)for(int x=0;x<width;x++){int pixel=y*width+x,color=Rgb(pixels,pixel);if(Match(color,background))continue;model[pixel]=true;countModel++;if((color>>16&255)>230&&(color>>8&255)>230&&(color&255)>230)white++;left=Math.Min(left,x);right=Math.Max(right,x);first=Math.Min(first,y);last=Math.Max(last,y);}
        if(countModel==0)return new Bitmap(source);
        bool flat=white>countModel*.9;int padding=Math.Max(12,(int)(Math.Max(right-left+1,last-first+1)*.10));
        left=Math.Max(0,left-padding);right=Math.Min(width-1,right+padding);first=Math.Max(top,first-padding);last=Math.Min(bottom,last+padding);
        int targetWidth=right-left+1,targetHeight=last-first+1,edgeWidth=Math.Max(1,Math.Min(width,bottom-top+1)/350);var output=new byte[targetWidth*targetHeight*4];
        for(int y=0;y<targetHeight;y++)for(int x=0;x<targetWidth;x++){
          int sx=left+x,sy=first+y,pixel=sy*width+sx,destination=(y*targetWidth+x)*4;Color color=Background;
          if(model[pixel]){
            if(flat){bool edge=sx<edgeWidth||sx>=width-edgeWidth||sy<top+edgeWidth||sy>bottom-edgeWidth||!model[pixel-edgeWidth]||!model[pixel+edgeWidth]||!model[pixel-edgeWidth*width]||!model[pixel+edgeWidth*width];int rgb=Rgb(pixels,pixel);bool face=(rgb>>16&255)>230&&(rgb>>8&255)>230&&(rgb&255)>230;color=edge||!face?Color.FromArgb(83,94,107):Color.FromArgb(174,184,195);}
            else color=Color.FromArgb(pixels[pixel*4+2],pixels[pixel*4+1],pixels[pixel*4]);
          }
          output[destination]=color.B;output[destination+1]=color.G;output[destination+2]=color.R;output[destination+3]=255;
        }
        var result=new Bitmap(targetWidth,targetHeight,System.Drawing.Imaging.PixelFormat.Format32bppArgb);var target=result.LockBits(new Rectangle(0,0,targetWidth,targetHeight),System.Drawing.Imaging.ImageLockMode.WriteOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);try{Marshal.Copy(output,0,target.Scan0,output.Length);}finally{result.UnlockBits(target);}return result;
      }
    }
  }
  internal static class Data {
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer(){MaxJsonLength=32*1024*1024};
    public static Dictionary<string,object> Map(object value){var typed=value as Dictionary<string,object>;return typed??Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
    public static string Text(IDictionary<string,object> map,string key){object value;return map.TryGetValue(key,out value)&&value!=null?Convert.ToString(value):"";}
    public static object[] Array(IDictionary<string,object> map,string key){object value;if(!map.TryGetValue(key,out value)||value==null)return new object[0];return ((IEnumerable)value).Cast<object>().ToArray();}
  }
