    void Route(){edges.Clear();var lanes=new List<PendingLane>();int colors=0;maxLanes=1;Func<int> vacant=()=>{int i=lanes.FindIndex(x=>x==null);return i<0?lanes.Count:i;};Action<int,PendingLane> assign=(i,p)=>{while(lanes.Count<=i)lanes.Add(null);lanes[i]=p;};for(int row=0;row<Rows.Count;row++){var commit=Rows[row];int lane=lanes.FindIndex(x=>x!=null&&x.Oid==commit.Oid);if(lane<0){lane=vacant();assign(lane,new PendingLane(){Oid=commit.Oid,Color=Dark.Lanes[colors++%Dark.Lanes.Length]});}var node=lanes[lane];commit.Lane=lane;commit.Color=node.Color;for(int i=0;i<lanes.Count;i++)if(lanes[i]!=null&&i!=lane)edges.Add(new Segment(){Row=row,From=i,To=i,Color=lanes[i].Color});lanes[lane]=null;for(int p=0;p<commit.Parents.Length;p++){string parent=commit.Parents[p];int to=lanes.FindIndex(x=>x!=null&&x.Oid==parent);if(to<0){to=p==0&&lanes[lane]==null?lane:vacant();assign(to,new PendingLane(){Oid=parent,Color=p==0?node.Color:Dark.Lanes[colors++%Dark.Lanes.Length]});}edges.Add(new Segment(){Row=row,From=lane,To=to,Color=lanes[to].Color});}maxLanes=Math.Max(maxLanes,lanes.Count);}}
