      var clip=g.Clip;g.SetClip(new Rectangle(0,HeaderHeight,width,Math.Max(0,Height-HeaderHeight)));int first=scroll.Value,last=Math.Min(Rows.Count,first+Math.Max(1,(Height-HeaderHeight)/RowHeight)+2);
