      for(int i=first;i<last;i++){var row=Rows[i];int y=HeaderHeight+(i-first)*RowHeight,center=y+RowHeight/2;using(var brush=new SolidBrush(row.Color))g.FillEllipse(brush,16+row.Lane*LaneWidth,center-4,8,8);if(row.Oid==Selected)using(var pen=new Pen(Dark.Foreground,1.4f))g.DrawEllipse(pen,13+row.Lane*LaneWidth,center-7,14,14);
