        DrawText(g,(row.Parents.Length>1?"Merge · ":"")+row.Message,new Rectangle(x,y,Math.Max(10,dateX-x-9),RowHeight),foreground,Font);DrawText(g,row.Date,new Rectangle(dateX,y,150,RowHeight),match?Dark.Muted:foreground,Dark.Small);DrawText(g,row.Author,new Rectangle(authorX,y,140,RowHeight),foreground,Dark.Small);DrawText(g,row.Oid.Substring(0,7),new Rectangle(commitX,y,85,RowHeight),match?Dark.Blue:foreground,Dark.Mono);
      }g.Clip=clip;
    }
    static void DrawText(Graphics g,string text,Rectangle bounds,Color color,Font font){if(bounds.Width>0)TextRenderer.DrawText(g,text,font,bounds,color,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix);}
    protected override void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);int maximum=Math.Max(0,Rows.Count-scroll.LargeChange);scroll.Value=Math.Max(0,Math.Min(maximum,scroll.Value-e.Delta/120*3));}
    CommitRow Hit(int y){int index=(y-HeaderHeight)/RowHeight+scroll.Value;return y<HeaderHeight||index<0||index>=Rows.Count?null:Rows[index];}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();var row=Hit(e.Y);if(row==null)return;if(e.Button==MouseButtons.Right){if(ContextCommit!=null)ContextCommit(row,e.Location);}else if(SelectedCommit!=null)SelectedCommit(row,(ModifierKeys&(Keys.Control|Keys.Shift))!=0);}
