    protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);int index=Rows.FindIndex(r=>r.Oid==Selected);if(e.KeyCode==Keys.Down||e.KeyCode==Keys.Up){index=Math.Max(0,Math.Min(Rows.Count-1,index+(e.KeyCode==Keys.Down?1:-1)));if(index>=0&&index<Rows.Count&&SelectedCommit!=null){if(index<scroll.Value)scroll.Value=index;else if(index>=scroll.Value+scroll.LargeChange)scroll.Value=index-scroll.LargeChange+1;SelectedCommit(Rows[index],e.Control||e.Shift);}e.Handled=true;}}
  }
