    void OnProgress(string message){if(Alive)status.Text=message;}
    void OnPreviewFinished(){NotifyDocumentChanged();}
    public void NotifyDocumentChanged(){if(!Alive||controller.IsPreviewRendering)return;refreshDue=DateTime.UtcNow.AddMilliseconds(350);}
    void UpdateCadContext(){if(!Alive||controller.IsPreviewRendering)return;RenderCadContext(controller.CurrentCadContext());}
    void RenderCadContext(CadContext context){ContextUpdates++;cadLabel.Text=(context.Kind.Length==0?"":context.Kind+" · "+context.Name+Environment.NewLine)+context.State;checkpoint.Enabled=context.CanSave;cadSignature=context.Signature+"|"+controller.Settings.Workspace;if(graph!=null&&!graph.IsDisposed)graph.ApplyCadContext(context);}
    void PollHostContext(){if(!Alive||controller.IsPreviewRendering)return;var now=DateTime.UtcNow;if(now>=nextContextPoll){nextContextPoll=now.AddSeconds(1);var context=controller.CurrentCadContext();if(cadSignature!=context.Signature+"|"+controller.Settings.Workspace){RenderCadContext(context);NotifyDocumentChanged();}}if(now>=refreshDue&&!controller.IsBusy){refreshDue=DateTime.MaxValue;RefreshStatus();}}
    public void Start(){sizing.Start();BeginInvoke(new Action(()=>{if(Alive)RefreshStatus();}));}
    void RefreshStatus(){controller.StartUi(()=>RefreshStatusAsync());}
    async Task RefreshStatusAsync(){
      if(!Alive)return;if(statusRefreshing){refreshAgain=true;return;}statusRefreshing=true;
      try {
        UpdateCadContext();string workspace=controller.Workspace();var value=Data.Map(await controller.Dispatch("status",new Dictionary<string,object>(),workspace));var data=Data.Map(await Task.Run(()=>GitpolarPane.Graph(workspace,"","")));if(!Alive)return;
        mini.LoadRows(Data.Array(data,"commits").Select(CommitRow.Read),Data.Array(data,"refs").Select(GraphRef.Read),true);
        status.Text=controller.Repository(workspace)+"\n"+Data.Text(value,"branch")+" · "+Data.Array(value,"files").Length+" 个本地改动\n"+(String.IsNullOrEmpty(controller.Settings.LastCheckpointAt)?"尚无一键保存记录":"最近保存："+controller.Settings.LastCheckpointAt.Replace('T',' '))+"\n"+workspace;
      }catch(Exception error){if(Alive)status.Text=controller.HasConfiguredRepository?error.Message:"选择 Git 工作副本后，即可保存与查看历史。";}
      finally{statusRefreshing=false;if(Alive){UpdateCadContext();if(refreshAgain){refreshAgain=false;refreshDue=DateTime.UtcNow.AddMilliseconds(250);}}}
    }
