    async Task SetBusy(Func<Task> action){if(!Alive||loading)return;loading=true;commit.Enabled=false;quick.Enabled=false;more.Enabled=false;UseWaitCursor=true;try{await action();}catch(Exception error){Log.Write(error.ToString());if(Alive){status.Text=error.Message;MessageBox.Show(this,error.Message,"gitpolar",MessageBoxButtons.OK,MessageBoxIcon.Information);}}finally{loading=false;if(Alive){commit.Enabled=true;quick.Enabled=controller.CachedCadContext.CanSave&&!controller.IsPreviewRendering;more.Enabled=true;UseWaitCursor=false;}}}
    public void RefreshGraph(){controller.StartUi(()=>RefreshGraphAsync());}
    async Task RefreshGraphAsync(){await SetBusy(async()=>{workspace=controller.Workspace();Text="Git Graph · "+controller.Repository(workspace)+" · SolidWorks";string scope=Scope;var value=Data.Map(await Task.Run(()=>GitpolarPane.Graph(workspace,scope,"")));if(!Alive)return;references=Data.Array(value,"refs").Select(GraphRef.Read).ToList();cursor=Data.Text(value,"nextCursor");changing=true;try{repository.Items.Clear();repository.Items.Add(controller.Repository(workspace));repository.Items.Add("选择工作副本…");repository.SelectedIndex=0;branches.Items.Clear();branches.Items.Add("Show All");foreach(var reference in references.Where(r=>r.Type!="tag"))branches.Items.Add(reference);int selectedIndex=0;for(int i=1;i<branches.Items.Count;i++)if(((GraphRef)branches.Items[i]).FullName==scope)selectedIndex=i;branches.SelectedIndex=selectedIndex;}finally{changing=false;}graph.LoadRows(Data.Array(value,"commits").Select(CommitRow.Read),references,true);more.Visible=!String.IsNullOrEmpty(cursor);var state=Data.Map(await controller.Dispatch("status",new Dictionary<string,object>(),workspace));if(!Alive)return;sidebar.Read(references,state);branchState.Text="⑂  "+Data.Text(state,"branch");if(!split.Panel1Collapsed)split.SplitterDistance=Math.Min(Math.Max(180,30+graph.Rows.Count*24+18),Math.Max(180,split.Height/3));status.Text=graph.Rows.Count+" commits · "+Data.Text(state,"branch")+" · "+Data.Array(state,"files").Length+" local changes · "+workspace;if(graph.Rows.Count>0){string oid=graph.Rows.Any(c=>c.Oid==selected)?selected:graph.Rows[0].Oid;await Select(oid);}});}
    async Task LoadMore(){if(String.IsNullOrEmpty(cursor))return;await SetBusy(async()=>{string next=cursor,scope=Scope;var data=Data.Map(await Task.Run(()=>GitpolarPane.Graph(workspace,scope,next)));if(!Alive)return;cursor=Data.Text(data,"nextCursor");graph.LoadRows(Data.Array(data,"commits").Select(CommitRow.Read),references,false);more.Visible=!String.IsNullOrEmpty(cursor);status.Text=graph.Rows.Count+" commits loaded";});}
    void UpdateSelection(){graph.Selected=selected;graph.ComparisonBase=baseline;graph.Invalidate();selection.Text=String.IsNullOrEmpty(baseline)?(String.IsNullOrEmpty(selected)?"Select a commit to view details":"Selected: "+selected.Substring(0,7)+"   ·   Ctrl+click another commit to compare"):"Compare: "+baseline.Substring(0,7)+" ↔ "+(String.IsNullOrEmpty(selected)?"…":selected.Substring(0,7));openBase.Enabled=!String.IsNullOrEmpty(baseline)&&baseline!=selected;}
    async Task Select(string oid){if(!Alive)return;CancelPreview();selected=oid;UpdateSelection();int version=++detailVersion;try{var result=Data.Map(await Task.Run(()=>GitpolarPane.Details(workspace,oid)));if(!Alive||version!=detailVersion)return;detail=result;summary.Read(result,oid);metadata.Text=Data.Text(result,"message").Trim()+Environment.NewLine+Data.Text(result,"author")+"  "+Data.Text(result,"date")+Environment.NewLine+oid+Environment.NewLine+"Parents: "+String.Join("  ",Data.Array(result,"parents").Select(p=>Convert.ToString(p).Substring(0,7)));filesChanging=true;files.BeginUpdate();try{files.Items.Clear();foreach(var file in Data.Array(result,"files").Select(Data.Map).Where(f=>!Data.Text(f,"path").StartsWith(".gitpolar/"))){string name=Data.Text(file,"path"),state=Data.Text(file,"status");var item=new ListViewItem(name){Tag=name};item.SubItems.Add(state);item.ForeColor=state=="A"?Dark.Lanes[3]:state=="D"?Dark.Lanes[4]:Dark.Foreground;files.Items.Add(item);}string active=controller.ActivePath();if(String.IsNullOrEmpty(selectedPath)&&!String.IsNullOrEmpty(active)&&active.StartsWith(workspace+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))selectedPath=active.Substring(workspace.Length+1).Replace('\\','/');if(String.IsNullOrEmpty(selectedPath))selectedPath=files.Items.Cast<ListViewItem>().Where(i=>IsCAD(Convert.ToString(i.Tag))).Select(i=>Convert.ToString(i.Tag)).FirstOrDefault()??"";var selectedItem=files.Items.Cast<ListViewItem>().FirstOrDefault(i=>Convert.ToString(i.Tag)==selectedPath);if(selectedItem!=null){selectedItem.Selected=true;selectedItem.EnsureVisible();}}finally{files.EndUpdate();filesChanging=false;}fileTree.LoadFiles(files.Items.Cast<ListViewItem>(),selectedPath);await Preview();}catch(Exception error){if(Alive&&version==detailVersion)status.Text=error.Message;}}
    static bool IsCAD(string file){return new string[]{".sldprt",".sldasm",".slddrw"}.Contains(Path.GetExtension(file).ToLowerInvariant());}
    void CancelPreview(){previewVersion++;previewLoading=false;var previous=activePreview;activePreview=null;if(previous!=null)previous.Cancel();}
    async Task Preview(){
      if(!Alive)return;CancelPreview();int version=previewVersion;var request=new CancellationTokenSource();activePreview=request;
      DisposeImage(before);DisposeImage(after);beforeError=afterError="";beforeNote.Text=afterNote.Text="";bool compare=!String.IsNullOrEmpty(baseline)&&baseline!=selected;previews.ColumnStyles[0].Width=compare?50:100;previews.ColumnStyles[1].Width=compare?50:0;after.Visible=afterTitle.Visible=afterNote.Visible=compare;beforeTitle.Text=(compare?"修改前  "+baseline.Substring(0,7):selected.Length>=7?selected.Substring(0,7):"Preview")+" · "+Path.GetFileName(selectedPath);afterTitle.Text="修改后  "+(selected.Length>=7?selected.Substring(0,7):"");open.Enabled=IsCAD(selectedPath);
      before.Message=after.Message=IsCAD(selectedPath)?"正在生成实体预览…":"选择零件或装配体以预览";
      try {
        if(!IsCAD(selectedPath)){status.Text="选择零件或装配体以预览";return;}previewLoading=true;status.Text="正在读取对应提交的实体预览…";string left=compare?baseline:selected,right=selected,file=selectedPath;
        bool leftOk=await RenderSide(before,beforeNote,left,file,version,request.Token);if(!Alive||version!=previewVersion)return;
        bool rightOk=!compare||await RenderSide(after,afterNote,right,file,version,request.Token);if(!Alive||version!=previewVersion)return;
        status.Text=Path.GetFileName(file)+" · "+(leftOk&&rightOk?(compare?"两侧实体预览已就绪":"实体预览已就绪"):leftOk||rightOk&&compare?"部分预览未完成，请查看对应提示":"预览未完成，请查看对应提示");
      } finally {if(version==previewVersion){previewLoading=false;activePreview=null;}request.Dispose();}
    }
    async Task<bool> RenderSide(CadPreviewCanvas canvas,Label note,string oid,string file,int version,CancellationToken cancellation){
      try {Image image=await controller.Thumbnail(workspace,oid,file,cancellation);if(!Alive||version!=previewVersion){if(image!=null)image.Dispose();return false;}canvas.Image=image;canvas.Message=image==null?"该版本暂无实体预览":"";note.Text=image==null?"预览未完成":Convert.ToString(image.Tag);return image!=null;}
      catch(OperationCanceledException){return false;}
      catch(Exception error){Log.Write(error.ToString());if(Alive&&version==previewVersion){canvas.Message=error.Message;note.Text="预览未完成";if(canvas==before)beforeError=error.Message;else afterError=error.Message;}return false;}
    }
    async Task OpenHistory(bool useBase){if(String.IsNullOrEmpty(selectedPath))return;await SetBusy(async()=>{await controller.OpenSnapshot(workspace,useBase?baseline:selected,selectedPath);if(!Alive)return;status.Text="历史图纸已在 SolidWorks 中只读打开";WindowState=FormWindowState.Minimized;});}
    void Context(CommitRow row,Point point){var menu=new ContextMenuStrip(){BackColor=Dark.Panel,ForeColor=Dark.Foreground,ShowImageMargin=false};Action<string,Action> item=(text,action)=>menu.Items.Add(text,null,(s,e)=>action());item("View Commit Details",()=>controller.StartUi(()=>Select(row.Oid)));item("Select for Comparison",()=>controller.StartUi(async()=>{baseline=row.Oid;await Select(row.Oid);}));if(!String.IsNullOrEmpty(baseline)&&baseline!=row.Oid)item("Compare with Selected Commit",()=>controller.StartUi(()=>Select(row.Oid)));menu.Items.Add(new ToolStripSeparator());item("Create Branch…",()=>{if(BranchesRequested!=null)BranchesRequested(row.Oid);});var local=references.Where(r=>r.Oid==row.Oid&&r.Type=="branch").ToList();foreach(var branch in local){var captured=branch;item("Checkout "+branch.Name,()=>controller.StartUi(()=>Run("checkout",new Dictionary<string,object>{{"name",captured.Name}})));}if(!String.IsNullOrEmpty(selectedPath)&&IsCAD(selectedPath))item("Open CAD at this Commit in SolidWorks",()=>controller.StartUi(async()=>{await Select(row.Oid);if(Alive)await OpenHistory(false);}));menu.Items.Add(new ToolStripSeparator());item("Copy Commit Hash",()=>Clipboard.SetText(row.Oid));menu.Closed+=(s,e)=>menu.Dispose();menu.Show(graph,point);}
    void ShowRepositoryMenu(Control owner){var menu=new ContextMenuStrip(){BackColor=Dark.Panel,ForeColor=Dark.Foreground,ShowImageMargin=false};menu.Items.Add("选择本地工作副本…",null,(s,e)=>{if(ConnectionDialog.Configure(controller,this))RefreshGraph();});menu.Items.Add("Pull (fast-forward only)",null,controller.UiEvent(()=>Run("pull")));menu.Items.Add("从当前提交创建分支…",null,controller.UiEvent(async()=>{if(String.IsNullOrEmpty(selected))return;string name=Prompt("Create Branch","分支名称","");if(name!=null)await Run("create-branch",new Dictionary<string,object>{{"name",name},{"oid",selected}});}));menu.Items.Add("导出当前提交图截图…",null,(s,e)=>{using(var save=new SaveFileDialog(){Filter="PNG image|*.png",FileName="gitpolar-git-graph.png"}){if(save.ShowDialog(this)==DialogResult.OK){SaveScreenshot(save.FileName);status.Text="截图已保存："+save.FileName;}}});menu.Items.Add("查看插件日志",null,(s,e)=>{string file=Path.Combine(Log.DirectoryPath,"plugin.log");if(File.Exists(file))Process.Start("notepad.exe",Git.Quote(file));});menu.Closed+=(s,e)=>menu.Dispose();menu.Show(owner,new Point(Math.Max(0,owner.Width-200),owner.Height));}
    string Prompt(string title,string label,string value){using(var form=new Form(){Text=title,Width=500,Height=190,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){Dark.Form(form);var heading=Dark.Label(label);heading.SetBounds(12,12,455,25);var input=Dark.Input(value);input.SetBounds(18,50,445,25);var ok=Dark.Button("Create",null);ok.SetBounds(370,92,90,30);ok.Click+=(s,e)=>{if(!String.IsNullOrWhiteSpace(input.Text))form.DialogResult=DialogResult.OK;};form.Controls.AddRange(new Control[]{heading,input,ok});form.AcceptButton=ok;return form.ShowDialog(this)==DialogResult.OK?input.Text.Trim():null;}}
    async Task Run(string action,Dictionary<string,object> values=null){await SetBusy(async()=>{await controller.Dispatch(action,values??new Dictionary<string,object>(),workspace);});if(Alive)await RefreshGraphAsync();}
    async Task SaveCommit(){Dictionary<string,object> state=null;await SetBusy(async()=>{state=Data.Map(await controller.Dispatch("prepare-commit",new Dictionary<string,object>(),workspace));});if(state==null||!Alive)return;using(var dialog=new CommitDialog(Data.Array(state,"files").Select(Data.Map).Where(f=>!Data.Text(f,"path").StartsWith(".gitpolar/")),IsCAD(controller.ActivePath()),!String.IsNullOrEmpty(Git.Try(workspace,"remote","get-url","origin")))){if(dialog.ShowDialog(this)==DialogResult.OK)await Run("commit",dialog.Values);}}
  }
  internal sealed class CommitDialog:EditorForm {
    readonly CheckedListBox list=new CheckedListBox();readonly TextBox message=Dark.Input("");readonly CheckBox preview=new CheckBox(){Text="生成当前零件 / 装配体的增量预览",Checked=true,AutoSize=true,ForeColor=Dark.Foreground},push=new CheckBox(){Text="提交后 Push 到 NAS（Git LFS）",Checked=true,AutoSize=true,ForeColor=Dark.Foreground};
